config.command:
set -euo pipefail
BASE={{ project_path }}
cd "$BASE" || { echo 'frontend-metrics: working directory not reachable'; exit 0; }
if [ ! -f scripts/public-readiness/frontend-metrics.sh ]; then
  echo '## summary'
  echo 'error=script_missing'
  exit 0
fi
# Read-only, no npm and no node_modules — a few seconds.
bash scripts/public-readiness/frontend-metrics.sh "$BASE" | awk '
  # No rule evaluates ## packages (directory edges); directory coupling is in ## coupling.
  # ## files is the complete table per module, ## recent the changes of the last 7 days —
  # inputs of the classification and of the candidate choice in block arch_metrics.
  /^## / { inpk = ($0 == "## packages" || $0 == "## files" || $0 == "## recent") }
  inpk && $0 == "## packages" { print; print "# omitted: directory coupling is in ## coupling"; next }
  inpk && $0 == "## files" { print; print "# omitted: table per module, input of the classification (## findings in block arch_metrics)"; next }
  inpk && $0 == "## recent" { print; print "# omitted: changes of the last 7 days, input of ## review_candidates in block arch_metrics"; next }
  inpk && NF == 0 { print; next }
  inpk { next }
  { print }'
